 * SQL statement splitting utilities for the JavaScript bindings.
 *
 * This module exists because the JS bindings don't expose an ergonomic way to
 * execute multiple statements while capturing results from the last one:
 * - db.exec(sql)     - executes multiple statements but doesn't return row data
 * - db.prepare(sql)  - returns rows but only handles a single statement
 *
 * So callers split a SQL script into individual statements themselves. A naive
 * split on ';' is wrong for triggers: a CREATE TRIGGER definition has a
 * BEGIN...END body that legitimately contains several ';'-terminated
 * sub-statements, and the whole definition must be handed to the database as a
 * single statement. This splitter keeps trigger bodies intact.
 */

/**
 * Classify the leading keyword sequence of a statement.
 *
 * Recognizes the trigger-creation forms:
 *   CREATE TRIGGER ...
 *   CREATE TEMP|TEMPORARY TRIGGER ...
 *   EXPLAIN [QUERY PLAN] CREATE [TEMP|TEMPORARY] TRIGGER ...
 *
 * @param {string[]} head Uppercased leading words seen so far.
 * @returns {'trigger'|'not'|'unknown'} 'unknown' means more words are needed
 *   before a decision can be made.
 */
function classifyHead(head) {
    let idx = 0;

    // Optional EXPLAIN [QUERY PLAN] prefix.
    if (head[idx] === 'EXPLAIN') {
        idx++;
        if (head[idx] === 'QUERY') {
            if (head[idx + 1] === 'PLAN') {
                idx += 2;
            } else if (head.length < idx + 2) {
                return 'unknown';
            } else {
                // EXPLAIN QUERY <something-else> is not a trigger form.
                return 'not';
            }
        }
    }

    // Required CREATE.
    if (head.length <= idx) return 'unknown';
    if (head[idx] !== 'CREATE') return 'not';
    idx++;

    // Optional TEMP / TEMPORARY.
    if (head.length <= idx) return 'unknown';
    if (head[idx] === 'TEMP' || head[idx] === 'TEMPORARY') idx++;

    // Required TRIGGER.
    if (head.length <= idx) return 'unknown';
    return head[idx] === 'TRIGGER' ? 'trigger' : 'not';
}

const isWordChar = (c) => c !== undefined && /[A-Za-z0-9_]/.test(c);

/**
 * Split a SQL string into an array of individual SQL statement strings.
 *
 * Each returned statement has its surrounding whitespace trimmed, while all
 * internal whitespace (newlines, indentation) is preserved exactly. Comments
 * and string literals are respected so that semicolons inside them do not split
 * a statement.
 *
 * Trigger definitions (CREATE TRIGGER, CREATE TEMP TRIGGER, and the
 * EXPLAIN CREATE TRIGGER variants) with a BEGIN...END body are returned as a
 * single element, regardless of how many ';'-terminated sub-statements appear
 * inside the body. A bare END keyword (matched case-insensitively, respecting
 * BEGIN/CASE nesting) terminates the trigger; the word END appearing inside a
 * string literal is ignored.
 *
 * @param {string} sql
 * @returns {string[]}
 */
export function splitStatements(sql) {
    const statements = [];
    const n = sql.length;
    let start = 0;
    let i = 0;

