    let head = [];          // leading uppercased words, for trigger detection
    let resolved = false;   // whether the statement kind has been classified
    let isTrigger = false;  // whether this statement is a trigger definition
    let inBody = false;     // whether the trigger's BEGIN body has started
    let depth = 0;          // BEGIN/CASE nesting depth within the trigger body
    let triggerEnded = false; // whether the trigger's closing END was reached

    const reset = (newStart) => {
        start = newStart;
        head = [];
        resolved = false;
        isTrigger = false;
        inBody = false;
        depth = 0;
        triggerEnded = false;
