    while (i < n) {
        const c = sql[i];
        const c2 = sql[i + 1];

        // Line comment: -- ... to end of line. Content is kept in the slice but
        // not parsed (so semicolons/quotes inside it are inert).
        if (c === '-' && c2 === '-') {
            i += 2;
            while (i < n && sql[i] !== '\n') i++;
            continue;
        }

        // Block comment: /* ... */
        if (c === '/' && c2 === '*') {
            i += 2;
            while (i < n && !(sql[i] === '*' && sql[i + 1] === '/')) i++;
            i += 2; // skip the closing */ (harmless overshoot at EOF)
            continue;
        }

        // String literal or quoted identifier. A doubled quote is an escaped
        // quote and does not close the literal.
        if (c === "'" || c === '"') {
            const quote = c;
            i++;
