                        continue;
                    }
                    i++;
                    break;
                }
                i++;
            }
            continue;
        }

        // Semicolon: a statement terminator, unless we are inside an unfinished
        // trigger definition.
        if (c === ';') {
            if (isTrigger && !triggerEnded) {
                i++;
                continue;
            }
            flush(i);
            i++;
            reset(i);
            continue;
