                    if (inBody) depth++;
                } else if (up === 'END') {
                    if (inBody) {
                        depth--;
                        if (depth === 0) triggerEnded = true;
                    }
                }
            }

            i = j;
            continue;
        }

        i++;
    }

    flush(n);
    return statements;
}

